const body = $input.first().json.body || $input.first().json;
const employee = {
  name: body.name || '',
  email: body.email || '',
  position: body.position || '',
  department: body.department || '',
  managerEmail: body.managerEmail || '',
  lastDay: body.lastDay || '',
  reason: body.reason || '',
  resignationDate: new Date().toISOString().slice(0, 10)
};
return [{ json: employee }];

const emp = $input.first().json;
const checklist = [
  { task: 'Disable email account', assignee: 'IT', deadline: emp.lastDay, status: 'pending' },
  { task: 'Revoke VPN and network access', assignee: 'IT', deadline: emp.lastDay, status: 'pending' },
  { task: 'Collect company laptop/equipment', assignee: 'IT', deadline: emp.lastDay, status: 'pending' },
  { task: 'Deactivate badge/building access', assignee: 'Security', deadline: emp.lastDay, status: 'pending' },
  { task: 'Remove from software subscriptions', assignee: 'IT', deadline: emp.lastDay, status: 'pending' },
  { task: 'Transfer project ownership', assignee: 'Manager', deadline: emp.lastDay, status: 'pending' },
  { task: 'Process final paycheck', assignee: 'Finance', deadline: emp.lastDay, status: 'pending' },
  { task: 'Calculate unused PTO payout', assignee: 'Finance', deadline: emp.lastDay, status: 'pending' },
  { task: 'COBRA/benefits termination notice', assignee: 'HR', deadline: emp.lastDay, status: 'pending' },
  { task: 'Update org chart', assignee: 'HR', deadline: emp.lastDay, status: 'pending' }
];
return [{ json: { ...emp, offboardingChecklist: checklist } }];
